Here's a complete example of modern data-driven MSTest tests for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // ─── DataRow: inline values for simple cases ───

    [TestMethod]
    [DataRow(10.00, 1, 10.00, DisplayName = "Single item")]
    [DataRow(25.50, 3, 76.50, DisplayName = "Multiple items")]
    [DataRow(0.00, 5, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_WithVariousInputs_ReturnsExpected(
        double price, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)price, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    // ─── DynamicData with ValueTuples: complex/decimal-precise data ───

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithVariousRates_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m, 0, 50m),
        (80m, 100, 0m),
        (0m, 50, 0m),
    ];

    // ─── Edge cases / validation ───

    [TestMethod]
    [DataRow(-1.0, 10)]
    [DataRow(100.0, -5)]
    [DataRow(100.0, 101)]
    public void ApplyDiscount_WithInvalidInput_Throws(double price, int discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, discountPercent));
    }
}
```

**Key points:**

- **`[DataRow]`** — best for simple inline values (note: `decimal` literals aren't allowed in attributes, so use `double` and cast)
- **`[DynamicData]` with ValueTuples** — preferred for `decimal`-precise data or complex objects (MSTest 3.7+)
- **Sealed class**, AAA pattern, descriptive `DisplayName`s
- **`Assert.ThrowsExactly<T>`** instead of `[ExpectedException]`
- No need for `[DataTestMethod]` — `[TestMethod]` handles data rows in MSTest 3.x+

Adjust the method signatures to match your actual `PriceCalculator` API.
